async function sendEmail(env, to, subject, bodyHtml) {
  if (!env.BREVO_API_KEY || !to) return { ok: false };
  try {
    const res = await fetch('https://api.brevo.com/v3/smtp/email', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'api-key': env.BREVO_API_KEY,
      },
      body: JSON.stringify({
        sender: { name: 'VIA-L Longevity', email: 'viaelcom@gmail.com' },
        to:      [{ email: to }],
        subject,
        htmlContent: `<div style="font-family:sans-serif;max-width:560px;margin:0 auto;color:#1A1008;line-height:1.7">`
          + bodyHtml
          + `<hr style="margin:32px 0;border:none;border-top:1px solid #EDE9E2">`
          + `<p style="color:#888;font-size:12px">VIA-L Longevity · <a href="https://via-l.com" style="color:#6B4F2A">via-l.com</a></p>`
          + `</div>`,
      }),
    });
    return res;
  } catch (_) { return { ok: false }; }
}

async function tgAnswerCallback(env, callbackQueryId, text, showAlert = false) {
  const res = await fetch(`https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/answerCallbackQuery`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ callback_query_id: callbackQueryId, text: text || '', show_alert: showAlert })
  });
  return res.json();
}

// Хелпер: возвращает строки секции «Onboarding-анамнез» для встраивания
// в карточку backstage-бота. Используется в /draft, когда с отчётом пришла
// анкета (поле onboarding в payload).
function renderOnboardingBlock(onb) {
  if (!onb || typeof onb !== 'object') return [];
  const out = ['', '🧬 <b>ELITE Onboarding — анамнез:</b>'];
  const add = (label, val) => {
    if (!val) return;
    const text = Array.isArray(val) ? val.join(', ') : val.toString();
    if (!text.trim()) return;
    out.push(`• <b>${esc(label)}:</b> ${esc(text.length > 200 ? text.slice(0, 200) + '…' : text)}`);
  };
  add('Цель',                  onb.goal);
  add('Опыт',                  onb.experience);
  add('Приоритет',             onb.priority);
  add('Telegram',              onb.telegram);
  add('Часовой пояс',          onb.timezone);
  add('Хронические',           onb.chronic);
  add('Лекарства',             onb.medications);
  add('Аллергии',              onb.allergies);
  add('Аутоиммунные',          onb.autoimmune);
  add('Изжога',                onb.heartburn);
  add('ИПП',                   onb.ppi);
  add('ИПП — препарат',        onb.ppi_detail);
  add('Антибиотики',           onb.antibiotics);
  add('Желчный удалён',        onb.gallbladder);
  add('Опыт с БАДами',         onb.supplements_history);
  return out;
}

// HTML-escape для Telegram parse_mode=HTML.
function esc(s) {
  if (s === null || s === undefined) return '';
  return s.toString()
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Selects up to 4 most relevant KB patterns (canonical P-F/P-M).
// Читает реальные поля/токены анкеты (не локализованный текст) — см. PATTERN-REGISTRY.md.
function selectKBPatterns(data) {
  const isFem  = data.gender !== 'male';
  let   phase  = data.phase || 'other';
  // Guard: мужчина не может быть в женской фазе (пери/мено/пост) → андропауза
  if (!isFem && (phase === 'peri' || phase === 'meno' || phase === 'post')) phase = 'andro';
  const bio    = data.bio  || {};
  const labs   = data.labs || {};
  const age    = parseInt(data.age) || 50;
  const energy = parseInt(data.energy) || 5;
  const anx    = parseInt(data.anxiety) || 0;
  const sleep  = parseInt(data.sleep_qual) || 5;
  const hrv    = parseInt(data.hrv) || 50;
  const temp   = data.temp || '';
  const wake   = data.wake || '';
  const fog    = data.fog || '';
  const memory = data.memory || '';
  let   visceral = bio.visceral != null && bio.visceral !== '' ? parseInt(bio.visceral) : null;
  const num = (v) => (v == null || v === '' ? null : parseFloat(v));
  // Мост талия/рост → псевдо-висцеральный индекс, когда прямого биоимпеданс-замера нет
  // (ручные тарифы вроде VIO). WHtR = талия/рост (нейтральный индекс, уже вводится клиентом);
  // маппим на пороги детектора visceral>9 (повышенный) и >12 (высокий), чтобы обмен/воспаление/
  // ССС-паттерны (P-F7/8/13/21, P-M3/4) не оставались слепыми при отсутствии весов.
  if (visceral == null) {
    const _wa = parseFloat(data.waist), _ht = parseFloat(data.height);
    if (_wa > 0 && _ht > 0) {
      const whtr = _wa / _ht;
      if (whtr >= 0.6) visceral = 13;
      else if (whtr >= 0.5) visceral = 10;
    }
  }

  // токены-массивы (значения чекбоксов анкеты)
  const sym  = Array.isArray(data.symptoms)      ? data.symptoms      : [];
  const horm = Array.isArray(data.horm_symptoms) ? data.horm_symptoms
             : ((data.horm_female || data.horm_male) ? Object.keys(Object.assign({}, data.horm_female || {}, data.horm_male || {})) : []);
  const cort = Array.isArray(data.cortisol_symp) ? data.cortisol_symp : [];
  const supp = Array.isArray(data.supplements)   ? data.supplements   : [];
  const gsm  = Array.isArray(data.gsm)           ? data.gsm           : [];
  const uro  = Array.isArray(data.urology)       ? data.urology       : [];
  const gi   = Array.isArray(data.gi)            ? data.gi            : [];
  const bone = Array.isArray(data.bone_risk)     ? data.bone_risk     : [];
  const breast = Array.isArray(data.breast)      ? data.breast        : [];
  // meds приходит массивом чекбоксов (VIO) ИЛИ строкой (иные потоки) — нормализуем в массив,
  // иначе сравнение data.meds === '...' на массиве всегда ложно и весь сигнал по лекарствам мёртв.
  const meds = Array.isArray(data.meds) ? data.meds : (data.meds ? [data.meds] : []);
  const has  = (arr, ...vals) => vals.some(v => arr.includes(v));

  const stressHigh  = data.chronic_stress === 'high' || data.chronic_stress === 'burnout' || data.chronic_stress === 'needs_recovery'
                   || /high|выс|hoch|élevé|alto/i.test(data.stress || '');
  const tempDown    = temp === 'down';
  const tempUnstable= temp === 'chaotic' || temp === 'spike';
  const lowEnergy   = energy <= 4;
  const tiredRecov  = data.act_recovery === 'tired' || data.act_recovery === 'exhausted' || data.act_recovery === 'spent';
  const hadHotflash = data.hf_count && data.hf_count !== 'none';
  const fogHi       = fog === 'daily' || fog === 'constant' || fog === 'allday';
  const memHi       = memory === 'poor' || memory === 'severe' || memory === 'slower' || memory === 'support';
  const cortLoad    = cort.filter(c => c && c !== 'none_cort').length >= 2;
  const deepLow     = data.deep === 'none' || data.deep === 'low';

  const selected = [];
  const add = (code, cond) => { if (cond) selected.push(code); };

  if (isFem) {
    // P-F1 эстроген — зонтик: дефицит (мено/пост) + доминирование/флукс (пери)
    add('P-F1', phase === 'post'
      || (phase === 'meno' && (data.hf_count === 'high' || has(horm,'dry_skin')))
      || (phase === 'peri' && (tempUnstable || hadHotflash || has(horm,'heavy_period','irregular_cycle'))));
    // P-F2 эстроген — метаболизм/детокс
    add('P-F2', phase === 'peri' && (has(horm,'heavy_period','weight_gain') || data.heavy_period === 'yes' || has(meds,'contraceptive','cycle_factor')));
    // P-F3 прогестерон
    add('P-F3', ((phase === 'peri' || phase === 'meno') && /multiple|early/i.test(wake) && anx >= 4)
      || data.pms === 'severe' || data.pms === 'moderate' || has(horm,'heavy_period') || data.heavy_period === 'yes');
    // P-F4 ГГН/кортизол
    add('P-F4', stressHigh || cortLoad
      || (hrv < 30 && (stressHigh || anx >= 6) && lowEnergy)
      || (num(labs.cort) != null && num(labs.cort) > 550));
    // P-F5 митохондрии (NEW)
    add('P-F5', lowEnergy && (tiredRecov || has(sym,'fatigue')) && (hrv < 30 || deepLow));
    // P-F6 щитовидка
    add('P-F6', (tempDown && lowEnergy) || (tempDown && has(horm,'hair_loss','weight_gain'))
      || has(sym,'cold','cool_sensitivity') || has(meds,'thyroid','energy_factor') || (num(labs.tsh) != null && num(labs.tsh) > 2.5));
    // P-F7 инсулинорезистентность
    add('P-F7', (visceral != null && visceral > 9) || has(horm,'weight_gain') || (data.appetite === 'cravings' || data.cravings === true)
      || num(labs.glucose) > 5.6 || num(labs.hba1c) > 5.7 || num(labs.homa) > 2.5);
    // P-F8 воспаление
    add('P-F8', has(sym,'joint','movement_stiff') || (visceral != null && visceral > 12) || num(labs.crp) > 3);
    // P-F9 нейромедиаторы (NEW)
    add('P-F9', anx >= 6 || data.mood === 'swings' || data.mood === 'low'
      || data.irritability === 'high' || has(sym,'anxiety','mood','restless_mind') || has(cort,'irritable'));
    // P-F10 когнитивный туман
    add('P-F10', fogHi || memHi || has(sym,'foggy'));
    // P-F11 кишечник
    add('P-F11', has(gi,'bloating','gi_heaviness','constipation','gi_slow','diarrhea','gi_fast','reflux','gi_inner') || has(supp,'probiotics'));
    // P-F12 кости
    add('P-F12', (phase === 'post' && (age >= 55 || (num(labs.vitd) != null && num(labs.vitd) < 50)))
      || has(bone,'load_sensitivity','posture_shift','hereditary_tone','balance_trait','prior_fracture','height_loss','family_osteoporosis','early_menopause'));
    // P-F13 сердечно-сосудистый
    add('P-F13', has(sym,'palpitations','pulse_awareness') || data.rhr_comp === 'high'
      || num(labs.ldl) > 3.4 || num(labs.apob) > 1.0 || num(labs.tg) > 1.7);
    // P-F14 кожа/коллаген (NEW)
    add('P-F14', has(horm,'dry_skin','hair_loss')
      || ((phase === 'post' || phase === 'meno') && age >= 50) || has(supp,'collagen'));
    // P-F15 GSM (вход из Шага 12: data.gsm)
    add('P-F15', has(gsm,'vaginal_dryness','dyspareunia','urinary_urgency','recurrent_uti','hydration_shift','comfort_need','pelvic_tension','pelvic_sensory')
      || has(horm,'libido_low')
      || ((phase === 'post' || phase === 'meno') && (data.cycle_status === 'absent' || data.last_period === 'year')));
    // P-F16 аутоиммунные (вход неполный)
    add('P-F16', has(meds,'thyroid','energy_factor') && num(labs.tsh) != null && num(labs.tsh) > 4);
    // P-F17 нарушения сна
    add('P-F17', sleep <= 4 || data.deep === 'none' || data.deep === 'low' || /multiple|many/i.test(wake) || (data.sleep_hours && data.sleep_hours < 6));
    // P-F18 B12/фолат
    add('P-F18', (num(labs.b12) != null && num(labs.b12) < 300) || has(sym,'numbness','sensory_shift')
      || (has(sym,'fatigue') && has(sym,'foggy')));
    // P-F19 аноректальное/проктология (прокси: запор/проктологические токены; вход неполный)
    add('P-F19', has(gi,'constipation','gi_slow','hemorrhoids','lower_sens','rectal_bleeding','lower_flag','fecal_incontinence','core_tone','straining','fiber_absorp','fiber_response'));
    // P-F20 тазовое дно: пролапс + недержание мочи (прокси: урология/GSM; вход неполный)
    add('P-F20', has(uro,'incontinence','stress_incontinence','urge_incontinence','support_shift','tone_shift','prolapse')
      || has(gsm,'incontinence','prolapse','support_shift','tone_shift')
      || ((phase === 'post' || phase === 'meno') && has(gsm,'urinary_urgency','pelvic_tension') && has(uro,'frequency','daytime_hydration')));
    // P-F21 здоровье груди / питание (вход из Шага 12: data.breast; + модифицируемый риск постменопаузы)
    add('P-F21', has(breast,'breast_pain','cyclic_comfort','breast_lump','tissue_tension','family_profile','family_breast_cancer','mastalgia')
      || has(horm,'breast_pain','breast_tenderness','breast_lump','mastalgia')
      || ((phase === 'post' || phase === 'meno') && (has(horm,'weight_gain') || (visceral != null && visceral > 9))));
  } else {
    // P-M1 тестостерон/андропауза
    add('P-M1', phase === 'andro'
      || (has(horm,'libido_male','muscle_loss','fatigue_chronic','intimacy_rhythm','muscle_tone','energy_baseline') && energy <= 5) || data.vitality === 'low');
    // P-M2 ГГН/кортизол
    add('P-M2', stressHigh || cortLoad || (hrv < 35 && stressHigh && anx >= 5));
    // P-M3 метаболический синдром
    add('P-M3', (visceral != null && visceral > 9) || has(horm,'belly_fat') || (data.appetite === 'cravings' || data.cravings === true)
      || num(labs.glucose) > 5.6 || num(labs.hba1c) > 5.7 || num(labs.homa) > 2.5);
    // P-M4 воспаление
    add('P-M4', has(sym,'joint','movement_stiff') || (visceral != null && visceral > 12) || num(labs.crp) > 3);
    // P-M5 щитовидка
    add('P-M5', (tempDown && lowEnergy) || has(sym,'cold','cool_sensitivity') || has(meds,'thyroid','energy_factor') || (num(labs.tsh) != null && num(labs.tsh) > 2.5));
    // P-M6 кишечник
    add('P-M6', has(gi,'bloating','gi_heaviness','constipation','gi_slow','diarrhea','gi_fast','reflux','gi_inner') || has(supp,'probiotics'));
    // P-M7 сердечно-сосудистый
    add('P-M7', has(sym,'palpitations','pulse_awareness') || data.rhr_comp === 'high'
      || num(labs.ldl) > 3.4 || num(labs.apob) > 1.0 || num(labs.tg) > 1.7);
    // P-M8 когнитивный туман
    add('P-M8', fogHi || memHi || has(sym,'foggy'));
    // P-M9 сон/СОАС
    add('P-M9', sleep <= 4 || data.deep === 'none' || data.deep === 'low' || /multiple|many/i.test(wake) || (data.sleep_hours && data.sleep_hours < 6));
    // P-M10 простата/ДГПЖ (вход из Шага 12: data.urology)
    add('P-M10', age >= 45 && has(uro,'nocturia','weak_stream','incomplete_emptying','frequency','night_waking','fluid_flow','pelvic_tone','daytime_hydration'));
    // P-M11 эректильная дисфункция как ССС-сигнал (прокси: ЭД-токен или низкое либидо + ССС-риск)
    add('P-M11', has(horm,'erectile','erectile_dysfunction','stamina_trend')
      || (has(horm,'libido_male','intimacy_rhythm') && ((visceral != null && visceral > 9)
          || data.rhr_comp === 'high' || num(labs.ldl) > 3.4 || num(labs.glucose) > 5.6 || num(labs.hba1c) > 5.7)));
  }

  // приоритизация: клинически центральные раньше, затем cap до 4
  const priority = isFem
    ? ['P-F1','P-F4','P-F3','P-F6','P-F7','P-F9','P-F17','P-F10','P-F5','P-F8','P-F13','P-F2','P-F12','P-F15','P-F20','P-F19','P-F14','P-F18','P-F11','P-F16','P-F21']
    : ['P-M1','P-M2','P-M3','P-M5','P-M9','P-M8','P-M7','P-M11','P-M4','P-M6','P-M10'];
  const uniq = [...new Set(selected)];
  uniq.sort((a, b) => priority.indexOf(a) - priority.indexOf(b));
  return uniq.slice(0, 4);
}

// Велнес-фильтр «корма» модели: buildUserMessage строит клинический дайджест данных.
// Для App Store-тарифов (VIO/PRO) прогоняем его через замены, чтобы модель не встречала
// (и не повторяла) мед-триггеры: диагнозы, гормоны-как-замеры, «ожирение», «менопауза».
// Корм внутренний (не показывается пользователю) — небольшие грам. огрехи допустимы; цель — убрать термины.
// EXPERT/ELITE (клиника) фильтр НЕ проходят. Порядок важен: специфичное раньше общего.
const _FEED_DEMED = [
  // ВАЖНО (JS-regex): \w и \b работают только с ASCII, НЕ с кириллицей. Окончания слов — через
  // [а-яё]* (с /i ловит и заглавные), кириллические аббревиатуры (ТТГ/АТ-ТПО) — без \b.
  // REFRAME: стадии-жизни (менопауза/перименопауза/андропауза/климакс) РЕТИРОВАНЫ — разрешены напрямую (как Apple Health).
  // вес / жир
  [/ожирени[а-яё]*\s*III/gi, 'очень высокий диапазон веса'],
  [/ожирени[а-яё]*\s*II/gi, 'высокий диапазон веса'],
  [/ожирени[а-яё]*\s*I\b/gi, 'повышенный диапазон веса'],
  [/ожирени[а-яё]*/gi, 'повышенный вес'],
  [/избыточная масса тела/gi, 'повышенный вес'],
  [/дефицит массы тела/gi, 'недостаточный вес'],
  [/метаболически тучн[а-яё]* при нормальном весе/gi, 'со скрытым внутренним жиром при нормальном весе'],
  [/метаболически тучн[а-яё]*/gi, 'со скрытым внутренним жиром'],
  [/абдоминальн[а-яё]* (?:накоплени[а-яё]* жира|ожирени[а-яё]*)/gi, 'накопление жира в области талии'],
  [/абдоминальн[а-яё]*/gi, 'в области талии'],
  [/висцеральн[а-яё]*/gi, 'внутренний (глубинный)'],
  // обмен / сахар
  [/кардиометаболическ[а-яё]* риск[а-яё]*/gi, 'зона внимания по обмену и энергии'],
  [/кардиометаболическ[а-яё]*/gi, 'по обмену веществ'],
  [/инсулинорезистентност[а-яё]*/gi, 'то, как тело отвечает на сахар'],
  [/ИР\/ожирения/gi, 'реакции на сахар и повышенного веса'],
  [/метаболическ[а-яё]* синдром[а-яё]*/gi, 'повышенная нагрузка обмена веществ'],
  [/метаболическ[а-яё]* нагрузк[а-яё]*/gi, 'нагрузка обмена веществ'],
  // REFRAME: гормон-имена (эстроген/прогестерон/тестостерон/кортизол/пролактин/эстрадиол/SHBG/гормон…) РЕТИРОВАНЫ —
  // разрешены напрямую в pattern-рамке. Оставлены лаб-МАРКЕРЫ ниже (ТТГ/АТ-ТПО/св.Т3-4) как measurement-claim guard:
  // прибор их НЕ измеряет, поэтому подавать как замер нельзя → де-медикализуем именно эти лаб-значения.
  [/ТТГ/g, 'ритмы обмена веществ'],
  [/АТ-ТПО/g, 'иммунный фон'],
  [/АТ-ТГ/g, 'иммунный фон'],
  [/обратный Т3/gi, 'обмен веществ'],
  [/св\.?\s*Т[34]/gi, 'обмен веществ'],
  [/Т4\s*→\s*Т3/gi, 'обмен веществ'],
  // диагнозы / органы
  [/гипотиреоз[а-яё]*/gi, 'замедленный обмен веществ'],
  [/гипертиреоз[а-яё]*/gi, 'ускоренный обмен веществ'],
  [/гипогонадизм[а-яё]*/gi, 'сниженная мужская витальность'],
  [/хашимото/gi, 'особенности иммунного фона'],
  [/тиреоидит[а-яё]*/gi, 'особенности иммунного фона'],
  [/аутоиммунн[а-яё]*/gi, 'связанный с иммунитетом'],
  [/щитовидн[а-яё]* желез[а-яё]*/gi, 'обмен веществ и энергия'],
  [/щитовидк[а-яё]*/gi, 'обмен веществ'],
  [/эндокринолог[а-яё]*/gi, 'специалисту'],
  // клинические протоколы/термины/имена (App Store 1.4.1) — велнес-замены
  [/\bCBT[-\s]?I\b/gi, 'вечерние привычки'],
  [/КПТ[-\s]?[ИиБб]?/g, 'вечерние привычки'],   // \b не работает с кириллицей — без границы
  [/Perry(?:\s*Academy)?/gi, 'велнес-практики'],
  [/Shelby\s*Harris/gi, 'велнес-эксперты'],
  [/бессонниц[а-яё]*/gi, 'беспокойный сон'],
  [/инсомни[а-яё]*/gi, 'беспокойный сон'],
  [/ПМС/g, 'маркеры комфорта перед новым ритмом'],   // VIO/PRO: убрать ПМС-ярлык из корма (App Store 1.4.1)
  [/предменструальн[а-яё]*/gi, 'перед новым ритмом'],
  // онко/остео/травма-триггеры (App Store 1.4.1) → велнес
  [/рак[а]?\s*груди[а-яё]*/gi, 'исторические особенности семейного профиля'],
  [/остеопороз[а-яё]*/gi, 'крепость и тонус опоры'],
  [/остеопени[а-яё]*/gi, 'крепость и тонус опоры'],
  [/уплотнени[а-яё]*(\s*\/\s*узел)?/gi, 'ощущение напряжения в тканях'],
  [/масталги[а-яё]*/gi, 'циклический дискомфорт'],
  // REFRAME 2026-07-11 (аудит опросника): бытовые симптомы РАЗРЕШЕНЫ напрямую (Apple Health symptom logging) —
  // ретайрены: перелом, вздутие/метеоризм/запор/диарея/жидкий стул/изжога/рефлюкс/жжение. Остаются ТАЗОВЫЕ состояния ниже.
  [/геморро[а-яё]*/gi, 'чувствительность нижнего отдела'],
  [/анальн[а-яё]* трещин[а-яё]*/gi, 'чувствительность нижнего отдела'],
  [/недержани[а-яё]*(\s*газов\s*\/?\s*кала)?/gi, 'тонус мышц центра тела'],
  [/натуживани[а-яё]*/gi, 'специфика усвоения клетчатки'],
  [/(неполн[а-яё]*\s*)?опорожнени[а-яё]*/gi, 'специфика усвоения клетчатки'],
  [/пролапс[а-яё]*|выпячивани[а-яё]*|опущени[а-яё]*/gi, 'ощущение глубокого тонуса'],
  // REFRAME (класс Б утверждён 2026-07-12): «антидепрессант/медикамент/лекарство/препарат/контрацепция/МГТ/ЗГТ/КОК»
  // РАЗРЕШЕНЫ напрямую (термин ≠ claim; лейблы UI ясные) — вокаб-эвфемизмы ретайрены. Claim-guard ОСТАЁТСЯ:
  // «заключения о совместимости/взаимодействии препаратов» → нейтрализуем; промпт запрещает советовать начать/сменить/отменить.
  [/(?:лекарственн[а-яё]*|препаратн[а-яё]*)\s*(?:взаимодействи[а-яё]*|совместимост[а-яё]*)/gi, 'сочетание велнес-ориентиров'],
  [/терапи[а-яё]*\s*перв[а-яё]*\s*лини[а-яё]*/gi, 'первый шаг образа жизни'],
  // общая клин. лексика
  [/нутритивн[а-яё]*\s*поддержк[а-яё]*/gi, 'велнес-поддержка'],
  [/нутритивн[а-яё]*/gi, 'велнес-поддержка'],
  [/клиническ[а-яё]*/gi, 'велнес'],
  [/противовоспалительн[а-яё]*/gi, 'поддерживающий'],
  [/воспалени[а-яё]*/gi, 'фоновая нагрузка'],
  // REFRAME: «симптом» и «дефицит» РЕТИРОВАНЫ (термины — Apple Health «symptom logging»). «диагноз/патология» = claim → остаются.
  [/диагноз[а-яё]*/gi, 'ориентир'],
  [/патологи[а-яё]*/gi, 'особенность'],
];
function deMedicalizeFeed(text) {
  return _FEED_DEMED.reduce((s, [re, to]) => s.replace(re, to), text);
}

function buildUserMessage(data, lang, tier) {
  const isFem = data.gender !== 'male';
  // Велнес (VIO/PRO) НЕ оценивает медицинский риск. Раньше сюда уходил готовый вердикт
  // («WHtR 0.53 (умеренный кардиометаболический риск)») — модель его лишь пересказывала, т.е. claim
  // рождался в НАШЕМ промпте, а не в модели (живой PRO 14.07 выдал «WHtR 0.53 — низкий риск по сердцу»,
  // да ещё и перепутав полосу). Для велнеса антропометрию отдаём паттерн-языком, без вердиктов.
  // EXPERT/ELITE (клиника) — оставляем как было.
  const isWell = ['vio', 'pro'].includes(String(tier || '').toLowerCase());
  const phaseMap = {
    peri: 'Перименопауза', meno: 'Менопауза', post: 'Постменопауза',
    andro: 'Андропауза', preandro: 'Предандропауза', other: 'Другое',
  };
  let phase = data.phase || 'other';
  // Guard: мужчина не может быть в женской фазе (пери/мено/пост) → андропауза
  if (!isFem && (phase === 'peri' || phase === 'meno' || phase === 'post')) phase = 'andro';
  const phaseName = phaseMap[phase] || phase;

  // ── REFERENCE NORMS ───────────────────────────────────────────
  const age = parseInt(data.age) || 50;
  const hrvNormLow  = age < 45 ? 40 : age < 55 ? 30 : 25;
  const hrvNormHigh = age < 45 ? 80 : age < 55 ? 65 : 55;
  const hrvVal      = parseInt(data.hrv) || 50;
  const hrvLow      = hrvVal < hrvNormLow;
  const hrvHigh     = hrvVal > hrvNormHigh;
  const hrvStatus   = hrvLow ? 'ниже нормы для возраста' : hrvHigh ? 'выше нормы — хорошее восстановление' : 'в норме для возраста';
  const rhrVal      = parseInt(data.rhr) || 68;
  const rhrHigh     = rhrVal > (isFem ? 75 : 70);
  const rhrLow      = rhrVal < (isFem ? 55 : 50);
  const rhrStatus   = rhrHigh ? 'повышен' : rhrLow ? 'отличный показатель' : 'в норме';
  const anxietyVal  = parseInt(data.anxiety) || 0;
  const energyVal   = parseInt(data.energy) || 5;
  const sleepQual   = parseInt(data.sleep_qual) || 5;
  const respRate    = parseInt(data.resp_rate) || 15;
  const deepSleep   = data.deep || '';
  const deepLow     = deepSleep === 'low' || deepSleep === 'none';
  const wakeVal     = data.wake || '';
  const multiWake   = /multiple|несколько|mehrmals|plusieurs|kilka|più volte|veces|כמה|数回|여러 번/i.test(wakeVal);
  const earlyWake   = /early|ранн|früh|madrugada|早|새벽|tôt/i.test(wakeVal);
  const symptoms    = data.symptoms || [];
  const stressHigh  = /high|выс|hoch|élevé|alto|hoog|高|높음/i.test(data.stress || '');
  const alcYes      = /yes|да|ja|oui|sí|sim|はい|네/i.test(data.alc || '');
  const tempDown    = /down|ниже|unter|bajo|abaixo|en dessous|poniżej|sotto|מתחת|低下|낮음/i.test(data.temp || '');
  const tempChaotic = /chaotic|хаот|chaos|caotique|caotico|カオス|혼란/i.test(data.temp || '');
  const tempSpike   = /spike|скачок|Sprung|pico|pointe|skok|picco|זינוק|急上昇|급등/i.test(data.temp || '');

  // ── ANTHROPOMETRY CALCULATIONS ────────────────────────────────
  const weightKg = parseFloat(data.weight) || null;
  const heightCm = parseFloat(data.height) || null;
  const waistCm  = parseFloat(data.waist)  || null;
  let bmiCalc = null, bmiCat = '', whtrCalc = null, whtrCat = '';
  if (weightKg && heightCm && heightCm > 0) {
    bmiCalc = weightKg / Math.pow(heightCm / 100, 2);
    bmiCat  = isWell
            ? (bmiCalc < 18.5 ? 'ниже типичного диапазона'
             : bmiCalc < 25   ? 'в типичном диапазоне'
             : bmiCalc < 30   ? 'выше типичного диапазона'
             : 'заметно выше типичного диапазона')          // велнес: без «ожирение I/II/III» — это болезнь-класс
            : (bmiCalc < 18.5 ? 'дефицит массы тела'
             : bmiCalc < 25   ? 'норма'
             : bmiCalc < 30   ? 'избыточная масса тела'
             : bmiCalc < 35   ? 'ожирение I'
             : bmiCalc < 40   ? 'ожирение II'
             : 'ожирение III');
  }
  if (waistCm && heightCm && heightCm > 0) {
    whtrCalc = waistCm / heightCm;
    const thr = isFem ? [0.42, 0.49, 0.58] : [0.43, 0.53, 0.63];
    whtrCat = isWell
            ? (whtrCalc < thr[0] ? 'ниже типичного диапазона'
             : whtrCalc < thr[1] ? 'в типичном диапазоне'
             : whtrCalc < thr[2] ? 'выше типичного диапазона'
             : 'заметно выше типичного диапазона')          // велнес: паттерн, НЕ оценка риска
            : (whtrCalc < thr[0] ? 'ниже нормы'
             : whtrCalc < thr[1] ? 'норма (низкий риск ССЗ)'
             : whtrCalc < thr[2] ? 'умеренный кардиометаболический риск'
             : 'высокий кардиометаболический риск');
  }
  // BMR (Mifflin-St Jeor) — вычисляется из веса/роста/возраста/пола; не требует биоимпеданса
  let bmrCalc = null, maintLow = null, maintHigh = null;
  if (weightKg && heightCm && heightCm > 0) {
    bmrCalc   = Math.round(10 * weightKg + 6.25 * heightCm - 5 * age + (isFem ? -161 : 5));
    maintLow  = Math.round(bmrCalc * 1.3);  // малоподвижный
    maintHigh = Math.round(bmrCalc * 1.5);  // лёгкая активность
  }

  // ── PATTERN DETECTION ─────────────────────────────────────────
  const patterns = [];

  if (hrvLow && anxietyVal >= 6 && stressHigh) {
    patterns.push('⚡ ПАТТЕРН А — Стресс-перегрузка: биометрия указывает на хроническую симпатическую активацию — HRV снижен, тревога высокая. Нутритивная поддержка: адаптогены + магний.');
  }
  if (isFem && multiWake && anxietyVal >= 5 && (phase === 'peri' || phase === 'meno')) {
    patterns.push('⚡ ПАТТЕРН B — Нарушение сна гормонального характера: множественные пробуждения + тревога в ' + phaseName + ' указывают на снижение успокаивающего влияния прогестерона. Нутритивная поддержка: магний глицинат вечером, витекс.');
  }
  if (isFem && phase === 'peri' && (tempChaotic || tempSpike) && data.hf_count && data.hf_count !== 'none') {
    patterns.push('⚡ ПАТТЕРН C — Нестабильность эстрогенового фона: хаотичная температура + приливы в перименопаузе. Нутритивная поддержка: крестоцветные (I3C/DIM), льняное семя, клетчатка ≥35 г/день.');
  }
  if (energyVal <= 4 && deepLow && data.hrv_trend === 'below') {
    patterns.push('⚡ ПАТТЕРН D — Дефицит клеточной энергии: низкая энергия + недостаток глубокого сна + падающий HRV. Нутритивная поддержка митохондрий: CoQ10 + магний.');
  }
  if (tempDown && energyVal <= 4 && symptoms.some(s => /волос|hair|когниц|cogn|память|memory|вес|weight/i.test(s))) {
    patterns.push('⚡ ПАТТЕРН E — Признаки замедления обмена веществ: температура ниже нормы + усталость + характерные симптомы. Нутритивная поддержка щитовидной железы: Se, Zn — рекомендуем обсудить с врачом.');
  }
  if (data.bio && parseInt(data.bio.visceral) > 9 && energyVal <= 5 && stressHigh) {
    patterns.push('⚡ ПАТТЕРН F — Метаболическая нагрузка: повышенный висцеральный жир + низкая энергия + стресс. Нутритивная поддержка: берберин, хром, приоритет белку и клетчатке.');
  }
  if (bmiCalc && bmiCalc >= 30) {
    const bmiNote = isWell
      ? 'Композиция тела выше типичного диапазона. Поддержка образом жизни: приоритет белку и клетчатке, силовые нагрузки, ходьба после еды.'
      : isFem
      ? 'ИМТ ≥30 в ' + phaseName + ': ↑ ароматаза → ↑ эстрон → риск эстрогенового доминирования + ↑ воспаление. Нутритивная поддержка: DIM 150 мг + крестоцветные ежедневно + берберин 500 мг × 2 + клетчатка ≥35 г + белок ≥1.4 г/кг.'
      : 'ИМТ ≥30: каждый SD ↑ ИМТ = −2.42 нмоль/л тестостерона. Нутритивная поддержка: берберин 500 мг × 2, цинк 25 мг, ашваганда 600 мг, ходьба 15 мин после еды, белок ≥1.6 г/кг.';
    patterns.push('⚡ ПАТТЕРН M1 (ИМТ ' + bmiCalc.toFixed(1) + ' — ' + bmiCat + ') — ' + bmiNote);
  }
  if (bmiCalc && bmiCalc >= 25 && bmiCalc < 30 && whtrCalc && whtrCalc >= (isFem ? 0.49 : 0.53)) {
    patterns.push('⚡ ПАТТЕРН M2 (ИМТ ' + bmiCalc.toFixed(1) + ', WHtR ' + whtrCalc.toFixed(2) + ') — ' + (isWell
      ? 'Больше жира в области талии при умеренном ИМТ; WHtR ' + whtrCat + '. Поддержка образом жизни: клетчатка, приоритет белку, ходьба после каждого приёма пищи.'
      : 'Абдоминальное накопление жира при умеренном ИМТ. WHtR указывает на ' + whtrCat + '. Нутритивная поддержка: берберин 500 мг × 2, клетчатка ≥35 г, ходьба 15 мин после каждого приёма пищи.'));
  }
  if (bmiCalc && bmiCalc < 25 && whtrCalc && whtrCalc >= (isFem ? 0.49 : 0.53)) {
    patterns.push('⚡ ПАТТЕРН M3 (ИМТ ' + bmiCalc.toFixed(1) + ', WHtR ' + whtrCalc.toFixed(2) + ') — ' + (isWell
      ? 'ИМТ в типичном диапазоне, но талия относительно роста ' + whtrCat + ' — то есть по одному ИМТ картину не увидеть. Поддержка образом жизни: меньше рафинированных углеводов, силовые нагрузки, ходьба после еды.'
      : '"Метаболически тучный при нормальном весе": скрытое абдоминальное ожирение. ИМТ вводит в заблуждение — WHtR точнее. Нутритивная поддержка: берберин, ограничение рафинированных углеводов, силовые нагрузки, ходьба после еды.'));
  }
  if (hrvLow && energyVal <= 3 && sleepQual <= 4 && !stressHigh) {
    patterns.push('⚡ ПАТТЕРН G — Признаки истощения адаптационных ресурсов: всё угнетено без ощущения стресса. Нутритивная поддержка: адаптогены мягкого действия, витамин C, B5.');
  }

  // ── CIRCADIAN / SLEEP ─────────────────────────────────────────
  const circadian = [];
  if (earlyWake) {
    circadian.push('Ранние пробуждения в 2–4 ч: могут быть связаны с колебаниями сахара или кортизолового ритма. Полезно: белковый перекус перед сном, магний глицинат 400 мг.');
  }
  if (multiWake) {
    circadian.push('Множественные пробуждения: фрагментируют восстановительные фазы сна — качество отдыха снижено даже при достаточной продолжительности.');
  }
  if (respRate > 20) {
    circadian.push('Частота дыхания ' + respRate + ' вд/мин выше нормы покоя (12–20): может указывать на напряжение нервной системы. Полезно: дыхательные практики вечером, L-теанин.');
  }
  if (deepSleep === 'none') {
    circadian.push('Очень мало глубокого сна: восстановительные процессы существенно снижены. Магний глицинат + отказ от экранов за 1 ч до сна — наиболее эффективная пара.');
  }
  if (alcYes) {
    circadian.push('Алкоголь накануне: нарушает восстановительные фазы сна и снижает HRV на 10–20%.');
  }

  // ── PHASE NUTRITIONAL PROTOCOL ────────────────────────────────
  let phaseProtocol = '';
  if (phase === 'peri') {
    phaseProtocol = 'НУТРИТИВНАЯ ПОДДЕРЖКА · ПЕРИМЕНОПАУЗА:\n'
      + '• Магний глицинат 300–400 мг вечером: сон, нервная возбудимость, >300 ферментативных реакций\n'
      + '• DIM 100–200 мг утром с едой: здоровый метаболизм эстрогена\n'
      + '• Льняное семя молотое 2 ст.л./день: лигнаны — мягкая фитоэстрогенная поддержка\n'
      + '• D3 2000–4000 МЕ + K2 100–200 мкг утром с жирной едой\n'
      + '• Ашваганда KSM-66 300–600 мг: стрессоустойчивость и качество сна\n'
      + '• Ограничить: алкоголь, кофеин после 14:00, рафинированный сахар';
  } else if (phase === 'meno') {
    phaseProtocol = 'НУТРИТИВНАЯ ПОДДЕРЖКА · МЕНОПАУЗА:\n'
      + '• Кальций цитрат 500–600 мг × 2/день с едой + D3 3000–4000 МЕ + K2 200 мкг\n'
      + '• Магний глицинат 400 мг вечером: сон, нервная система, углеводный обмен\n'
      + '• Омега-3 EPA/DHA 2–4 г/день: противовоспалительная поддержка, сердечно-сосудистая система\n'
      + '• Коллаген тип I/III 10–15 г + вит C 500 мг утром\n'
      + '• Белок ≥1.4–1.6 г/кг: поддержка мышечной массы';
  } else if (phase === 'post') {
    phaseProtocol = 'НУТРИТИВНАЯ ПОДДЕРЖКА · ПОСТМЕНОПАУЗА:\n'
      + '• D3 3000–5000 МЕ + K2 200 мкг + кальций цитрат 1200 мг: приоритет — кости\n'
      + '• CoQ10 (убихинол) 150–200 мг с завтраком: клеточная энергия, сердечно-сосудистая система\n'
      + '• Омега-3 3–4 г EPA/DHA: сердце, мозг, воспаление\n'
      + '• Берберин 500 мг × 2 с едой: поддержка сахара крови\n'
      + '• Белок ≥1.6 г/кг: приоритет для сохранения мышечной массы';
  } else if (phase === 'preandro') {
    phaseProtocol = 'НУТРИТИВНАЯ ПОДДЕРЖКА · ПРЕДАНДРОПАУЗА:\n'
      + '• Цинк цитрат 15–25 мг с едой: ключевой минерал мужского гормонального здоровья\n'
      + '• Магний глицинат 300–400 мг вечером: нервная система, сон, мышечное восстановление\n'
      + '• D3 2000–3000 МЕ + K2 100 мкг: участвует в регуляции мужского гормонального фона\n'
      + '• Омега-3 2–3 г EPA/DHA: противовоспалительная поддержка\n'
      + '• Ашваганда KSM-66 600 мг: адаптоген с доказанной поддержкой мужского здоровья\n'
      + '• Питание: тыквенные семечки (Zn), бразильский орех 2 шт/день (Se), крестоцветные';
  } else if (phase === 'andro') {
    phaseProtocol = 'НУТРИТИВНАЯ ПОДДЕРЖКА · АНДРОПАУЗА:\n'
      + '• Цинк 25–30 мг + селен 200 мкг: ключевые минералы гормонального здоровья\n'
      + '• D3 3000–5000 МЕ + K2 200 мкг: гормональный фон, кости, иммунитет\n'
      + '• CoQ10 (убихинол) 150–200 мг с завтраком: клеточная энергия, сердечно-сосудистая система\n'
      + '• Омега-3 3–4 г EPA/DHA: здоровье сердца, снижение воспаления\n'
      + '• Ашваганда 600 мг + панакс женьшень 200 мг утром: энергия и витальность\n'
      + '• Белок ≥1.6–2.0 г/кг + силовые тренировки 3×/нед';
  } else {
    phaseProtocol = 'БАЗОВАЯ НУТРИТИВНАЯ ПОДДЕРЖКА: Магний глицинат 300–400 мг вечером, D3 2000–3000 МЕ + K2 100 мкг утром с едой, омега-3 2–3 г EPA/DHA. Адаптоген: ашваганда 300–600 мг. Питание: средиземноморская база, белок ≥1.4 г/кг.';
  }

  // ── SYMPTOM → NUTRITIONAL SUPPORT ────────────────────────────
  const symRules = [];
  if (symptoms.some(s => /прилив|жар|flash|calor|Hitze|bouffée|vampata|גלי חום|ほてり|열감/i.test(s))) {
    symRules.push('Приливы: шалфей или чёрный кохош (растительная поддержка), магний 400 мг вечером, фитоэстрогены (кунжут, соя, льняное семя), исключить алкоголь + острое + кофе вечером');
  }
  if (symptoms.some(s => /сустав|arthri|joint|movement_stiff|dolor articular|Gelenk|articul|כאב מפרק|関節|관절/i.test(s))) {
    symRules.push('Суставный дискомфорт: коллаген тип II 40 мг натощак или тип I/III 10–15 г с витамином C, босвеллия 500 мг, омега-3 3–4 г');
  }
  if (symptoms.some(s => /туман|когни|brain fog|memoria|Gehirn|brouillard|mgła|nebbia|ערפל|脳霧|브레인 포그/i.test(s))) {
    symRules.push('Когнитивный туман: омега-3 DHA 1–2 г/день, фосфатидилсерин 300 мг утром, Lion\'s Mane 500–1000 мг');
  }
  if (symptoms.some(s => /волос|выпад|hair loss|alopecia|Haarausfall|chute.*cheveux|wypad|caduta|נשירת שיער|脱毛|탈모/i.test(s))) {
    symRules.push('Состояние волос: биотин 5000 мкг, цинк 15–25 мг, кремний органический 10–20 мг. Ферритин ниже 70 мкг/л — частая причина выпадения волос, стоит обсудить с врачом');
  }
  if (symptoms.some(s => /вес|набор|overweight|sobrepeso|Übergewicht|surpoids|nadwaga|sovrappeso|עודף משקל|体重増加|체중 증가/i.test(s))) {
    symRules.push('Управление весом: берберин 500 мг × 2 с едой, хром 200 мкг, акцент на белок и клетчатку, ограничение рафинированных углеводов');
  }
  if (symptoms.some(s => /тревог|паник|anxiety|restless_mind|ansiedad|Angst|anxiété|niepokój|ansia|חרדה|不安|불안/i.test(s))) {
    symRules.push('Тревожность: L-теанин 200 мг, магний глицинат 400 мг вечером, ашваганда 300–600 мг, ограничить кофеин после 12:00');
  }
  if (symptoms.some(s => /сухост|vaginal|libido|Libido|חשק|性욕|성욕/i.test(s))) {
    symRules.push('Либидо и сухость слизистых: омега-3 2–3 г, витамин E 400 МЕ, мака перуанская 1500–3000 мг');
  }

  // ── HOT FLASH CONTEXT ─────────────────────────────────────────
  let hfContext = '';
  if (isFem && data.hf_count && data.hf_count !== 'none') {
    const hfSev = data.hf_count === 'high' ? 'выраженные (6+/ночь)'
                : data.hf_count === 'mid'  ? 'умеренные (3–5/ночь)'
                : 'лёгкие (1–2/ночь)';
    hfContext = '\n- Приливы: ' + hfSev + (data.hf_intensity ? ' | интенсивность: ' + data.hf_intensity : '');
  }

  // ── SLEEP / LABS / BIO CONTEXT ────────────────────────────────
  const sleepStatus = sleepQual <= 4 ? 'неудовлетворительный' : sleepQual <= 6 ? 'нарушенный' : sleepQual <= 8 ? 'удовлетворительный' : 'хороший';
  const deepContext = deepSleep === 'good' ? '≥90 мин (норма)' : deepSleep === 'low' ? 'недостаточно (30–90 мин)' : deepSleep === 'none' ? 'очень мало (<30 мин)' : 'не указан';

  let labsContext = '';
  if (data.labs) {
    const l = data.labs;
    const notes = [];

    // ── Витамин D ──
    if (l.vitd) {
      const v = parseFloat(l.vitd);
      notes.push('Витамин D: ' + l.vitd + ' нмоль/л → ' + (v < 50 ? '[ниже оптимума — D3 приоритет]' : v < 75 ? '[нижняя зона нормы — поддерживающая доза полезна]' : '[хороший уровень ✓]'));
    }
    // ── Ферритин ──
    if (l.ferr) {
      const f = parseFloat(l.ferr);
      notes.push('Ферритин: ' + l.ferr + ' мкг/л → ' + (f < 30 ? '[низкий — целевой >70 мкг/л, объясняет усталость и выпадение волос]' : f < 70 ? '[субоптимальный]' : '[норма ✓]'));
    }
    // ── ТТГ (возраст-специфичный) ──
    if (l.tsh) {
      const t = parseFloat(l.tsh);
      const tshOpt = age < 40 ? 2.5 : age < 60 ? 4.0 : 4.9;
      notes.push('ТТГ: ' + l.tsh + ' мМЕ/л → ' + (t > tshOpt ? '[выше оптимума для возраста — Se 200 мкг + Zn 15 мг; обсудить с врачом]' : t < 0.5 ? '[низкий — обсудить с врачом]' : '[в норме ✓]'));
    }
    // ── сТ4, сТ3, rT3 ──
    if (l.ft4) {
      const v = parseFloat(l.ft4);
      notes.push('Св. Т4: ' + l.ft4 + ' пмоль/л → ' + (v < 12 ? '[низкий — гипотиреоз, к врачу]' : v > 22 ? '[высокий — гипертиреоз, к врачу]' : '[норма ✓]'));
    }
    if (l.ft3) {
      const v = parseFloat(l.ft3);
      notes.push('Св. Т3: ' + l.ft3 + ' пмоль/л → ' + (v < 3.5 ? '[низкий — Se, Zn для конверсии Т4→Т3; стресс и дефицит калорий снижают Т3]' : '[норма ✓]'));
    }
    if (l.rt3) {
      const v = parseFloat(l.rt3);
      notes.push('Обратный Т3: ' + l.rt3 + ' нг/дл → ' + (v > 15 ? '[повышен — хронический стресс/дефицит калорий блокируют рецепторы Т3; адаптогены + нормализация калорий]' : '[норма ✓]'));
    }
    // ── АТ-ТПО, АТ-ТГ ──
    if (l.tpo) {
      const v = parseFloat(l.tpo);
      notes.push('АТ-ТПО: ' + l.tpo + ' МЕ/мл → ' + (v > 35 ? '[Хашимото — Se 200 мкг ↓ АТ-ТПО (35 РКИ); глютен-элиминация 3 нед; к эндокринологу]' : '[норма ✓]'));
    }
    if (l.tgab) {
      const v = parseFloat(l.tgab);
      notes.push('АТ-ТГ: ' + l.tgab + ' МЕ/мл → ' + (v > 40 ? '[повышен — аутоиммунный тиреоидит; обсудить с врачом]' : '[норма ✓]'));
    }
    // ── Эстрадиол ──
    if (l.e2) {
      const e = parseFloat(l.e2);
      notes.push('Эстрадиол: ' + l.e2 + ' пг/мл → ' + (e < 20 ? '[низкий — фитоэстрогены, DIM, льняное семя]' : e < 50 ? '[сниженный]' : !isFem ? '[высокий у мужчины — DIM, крестоцветные, снижение веса]' : '[в диапазоне ✓]'));
    }
    // ── Тестостерон (мужчины) ──
    if (l.test) {
      const v = parseFloat(l.test);
      notes.push('Тестостерон общий: ' + l.test + ' нмоль/л → ' + (v < 9.2 ? '[дефицит — ашваганда 600 мг + Zn + D3 + силовые тренировки; обсудить с врачом]' : v < 15 ? '[нижняя зона нормы — нутритивная поддержка актуальна]' : '[норма ✓]'));
    }
    if (l.shbg) {
      const v = parseFloat(l.shbg);
      notes.push('SHBG: ' + l.shbg + ' нмоль/л → ' + (v > 50 ? '[высокий — снижает биодоступный тестостерон; снижение ИР повысит свободный T]' : v < 15 ? '[низкий — признак ИР/ожирения; ↑ свободный T, но ↑ арomatase]' : '[норма ✓]'));
    }
    if (l.lh) {
      const v = parseFloat(l.lh);
      notes.push('ЛГ: ' + l.lh + ' мМЕ/мл → ' + (v > 12 && !isFem ? '[повышен у мужчины — первичный гипогонадизм; к врачу]' : '[в контексте панели]'));
    }
    if (l.prolactin) {
      const v = parseFloat(l.prolactin);
      notes.push('Пролактин: ' + l.prolactin + ' мкг/л → ' + (v > 100 ? '[высокий — МРТ гипофиза обязательно; к врачу срочно]' : v > 25 ? '[умеренно повышен — проверить ТТГ, препараты; витекс при функциональной причине]' : '[норма ✓]'));
    }
    // ── Прогестерон (жен) ──
    if (l.prog) {
      const v = parseFloat(l.prog);
      notes.push('Прогестерон: ' + l.prog + ' нмоль/л → ' + (v < 3 ? '[низкий — при сохранённом цикле возможны ановуляция/дефицит лютеиновой фазы; магний глицинат вечером, витекс; обсудить с врачом]' : v < 10 ? '[нижняя зона лютеиновой фазы — поддержка магнием/витексом]' : '[в контексте фазы цикла]'));
    }
    // ── Кортизол утренний ──
    if (l.cort) {
      const v = parseFloat(l.cort);
      notes.push('Кортизол утренний: ' + l.cort + ' нмоль/л → ' + (v > 550 ? '[повышен — хронический стресс; ашваганда KSM-66, магний глицинат, режим сна 22:00–6:00; обсудить с врачом]' : v < 150 ? '[низкий — оценить функцию надпочечников у врача]' : '[в норме ✓]'));
    }
    // ── Метаболическая панель ──
    if (l.glucose) {
      const v = parseFloat(l.glucose);
      notes.push('Глюкоза натощак: ' + l.glucose + ' ммоль/л → ' + (v >= 7.0 ? '[диабет — к врачу]' : v >= 5.6 ? '[предиабет — берберин 500 мг × 2, клетчатка ≥35 г, ходьба 15 мин после еды]' : v >= 5.0 ? '[верхняя норма — следить, если есть ↑ инсулин]' : '[норма ✓]'));
    }
    if (l.homa) {
      const v = parseFloat(l.homa);
      notes.push('HOMA-IR: ' + l.homa + ' → ' + (v > 3.8 ? '[выраженная ИР — берберин + хром + снижение веса]' : v > 2.5 ? '[инсулинорезистентность — нутритивная поддержка актуальна]' : v > 1.4 ? '[ранняя ИР — профилактические меры]' : '[норма ✓]'));
    }
    if (l.hba1c) {
      const v = parseFloat(l.hba1c);
      notes.push('HbA1c: ' + l.hba1c + '% → ' + (v >= 6.5 ? '[диабет — к врачу]' : v >= 5.7 ? '[предиабет — средиземноморская диета + берберин]' : '[норма ✓]'));
    }
    if (l.ldl) {
      const v = parseFloat(l.ldl);
      notes.push('ЛПНП: ' + l.ldl + ' ммоль/л → ' + (v > 3.4 ? '[высокий — омега-3 + берберин + снижение насыщенных жиров]' : v > 2.6 ? '[умеренно повышен]' : '[норма ✓]'));
    }
    if (l.tg) {
      const v = parseFloat(l.tg);
      notes.push('Триглицериды: ' + l.tg + ' ммоль/л → ' + (v > 2.3 ? '[высокие — омега-3 ≥3 г EPA/сут, ↓ рафинированные углеводы и алкоголь]' : v > 1.7 ? '[умеренно повышены]' : '[норма ✓]'));
    }
    if (l.apob) {
      const v = parseFloat(l.apob);
      notes.push('ApoB: ' + l.apob + ' г/л → ' + (v > 1.2 ? '[высокий — ключевой маркер атерогенных частиц, превосходит ЛПНП; омега-3 + берберин + ↓ насыщенных жиров; обсудить с врачом]' : v > 1.0 ? '[умеренно повышен]' : '[норма ✓]'));
    }
    if (l.crp) {
      const v = parseFloat(l.crp);
      notes.push('hs-CRP: ' + l.crp + ' мг/л → ' + (v > 3.0 ? '[высокое воспаление — куркумин 1500 мг + омега-3 3–4 г + снижение висцерального жира]' : v > 1.0 ? '[умеренное воспаление]' : '[норма ✓]'));
    }

    if (notes.length) labsContext = '\nПОКАЗАТЕЛИ (нутритивный контекст):\n' + notes.join('\n');
  }

  let bioContext = '';
  if (data.bio) {
    const b = data.bio;
    const bn = [];
    // sanity-флаг: значения вне физиологичного диапазона (опечатка / сбой прибора)
    // НЕ подаём ИИ как факт — иначе он строит советы на мусоре (напр. «жир 3% — наберите вес»).
    if (b.fat) {
      const fv = parseFloat(b.fat);
      if (fv >= (isFem ? 10 : 5) && fv <= (isFem ? 55 : 50)) {
        const norm = isFem ? (age > 50 ? '28–38%' : '23–33%') : (age > 50 ? '18–28%' : '15–25%');
        bn.push('Жир: ' + b.fat + '% (ориентир ' + norm + ')');
      }
    }
    if (b.muscle) {
      const m = parseFloat(b.muscle);
      if (m >= 20 && m <= 65) {
        bn.push('Мышцы: ' + b.muscle + '%' + (m < (isFem ? 25 : 33) ? ' [ниже оптимума — белок + силовые тренировки]' : ' ✓'));
      }
    }
    if (b.visceral) {
      const vi = parseInt(b.visceral);
      if (vi >= 1 && vi <= 40) {  // шкала прибора 1–30 (запас до 40); >40 = ошибка ввода
        bn.push('Висцеральный жир: уровень ' + b.visceral + (vi > 9 ? ' [выше оптимума — метаболическая поддержка актуальна]' : ' ✓'));
      }
    }
    if (b.bioage) {
      const ba = parseInt(b.bioage);
      if (ba >= 18 && ba <= 120) {  // вне 18–120 = ошибка ввода, не подаём ИИ
        bn.push('Биовозраст: ' + b.bioage + ' лет' + (ba < age ? ' [моложе паспортного ✓]' : ba > age + 3 ? ' [выше паспортного — антивозрастная нутритивная поддержка актуальна]' : ''));
      }
    }
    if (bn.length) bioContext = '\nСОСТАВ ТЕЛА: ' + bn.join(' | ');
  }

  // ── ЖАЛОБЫ ПО СИСТЕМАМ (GSM / урология / ЖКТ-проктология → видит ИИ) ──
  const COMPLAINT_LBL = {
    // App Store 1.4.1 — велнес-лейблы (это ярлыки для «корма» ИИ; логика/ключи не меняются)
    vaginal_dryness:'интимный комфорт и увлажнённость', dyspareunia:'комфорт при близости', urinary_urgency:'сигналы мочевого комфорта', recurrent_uti:'чувствительность мочевого комфорта',
    hydration_shift:'интимный комфорт и увлажнённость', comfort_need:'комфорт при близости', pelvic_tension:'сигналы мочевого комфорта', pelvic_sensory:'чувствительность мочевого комфорта',
    stress_incontinence:'тонус мышц центра тела', urge_incontinence:'тонус мышц центра тела', support_shift:'тонус мышц центра тела', tone_shift:'тонус мышц центра тела', prolapse:'ощущение глубокого тонуса',
    nocturia:'ночные подъёмы', weak_stream:'ритм оттока', incomplete_emptying:'специфика усвоения клетчатки', frequency:'частота днём',
    night_waking:'ночные подъёмы', fluid_flow:'ритм оттока', pelvic_tone:'специфика усвоения клетчатки', daytime_hydration:'частота днём',
    bloating:'ощущение тяжести', gi_heaviness:'ощущение тяжести', constipation:'замедленный ритм', gi_slow:'замедленный ритм', diarrhea:'ускоренный ритм', gi_fast:'ускоренный ритм', reflux:'внутренний дискомфорт', gi_inner:'внутренний дискомфорт',
    rectal_bleeding:'чувствительность нижнего отдела', lower_flag:'чувствительность нижнего отдела', hemorrhoids:'специфика усвоения', lower_sens:'специфика усвоения', fecal_incontinence:'тонус мышц центра тела', core_tone:'тонус мышц центра тела', straining:'специфика усвоения клетчатки', fiber_absorp:'специфика усвоения клетчатки', fiber_response:'специфика усвоения клетчатки',
    heaviness:'внутренний дискомфорт', fissure:'чувствительность нижнего отдела', itch:'чувствительность нижнего отдела', fiber_spec:'специфика усвоения клетчатки', deep_tone:'ощущение глубокого тонуса',
    breast_pain:'циклический дискомфорт верхней части тела', cyclic_comfort:'циклический дискомфорт верхней части тела', breast_lump:'ощущение напряжения в тканях', tissue_tension:'ощущение напряжения в тканях', family_breast_cancer:'исторические особенности семейного профиля', family_profile:'исторические особенности семейного профиля',
  };
  const flagC = (arr) => (Array.isArray(arr) ? arr : []).filter(t => t && !String(t).startsWith('none') && COMPLAINT_LBL[t]).map(t => COMPLAINT_LBL[t]);
  const _gsmC = flagC(data.gsm), _uroC = flagC(data.urology), _giC = flagC(data.gi), _breastC = flagC(data.breast);
  const _compl = [];
  if (_gsmC.length) _compl.push('мочеполовое/интимное — ' + _gsmC.join(', '));
  if (_uroC.length) _compl.push('мочеиспускание/простата — ' + _uroC.join(', '));
  if (_giC.length)  _compl.push('ЖКТ/проктология — ' + _giC.join(', '));
  if (_breastC.length) _compl.push('грудь — ' + _breastC.join(', '));
  const complaintsContext = _compl.length
    ? 'ЖАЛОБЫ ПО СИСТЕМАМ (отметил клиент — затронь бережно и адресно, особенно деликатные/красные флаги): ' + _compl.join(' | ') + '\n'
    : '';

  // ── НЕ ВВЕДЁННЫЕ КЛИЕНТОМ ПОЛЯ (honest "не указано") ──
  // Фронт присылает _skipped — список «мягких» полей, которых клиент не трогал
  // (остались на дефолте). Их нельзя выдавать ИИ как реальные находки.
  const sk = new Set(Array.isArray(data._skipped) ? data._skipped : []);
  const SK = (k, s) => sk.has(k) ? 'не указано (клиент не вводил)' : s;
  // Конкретные ярлыки пропущенных полей — чтобы ИИ просил ИМЕННО недостающее, а не «данные о сне» вообще.
  const _SKIP_LBL = { sleep_qual:'ощущение сна', deep:'глубокий сон', wake:'ночные пробуждения',
    energy:'энергия днём', stress:'уровень стресса', anxiety:'уровень тревоги', mood:'настроение',
    irritability:'раздражительность', hf_count:'тепловые волны/ощущение тепла', rhr:'пульс покоя',
    hrv:'восстановление (кольцо/трекер)', hrv_trend:'тренд восстановления (трекер)',
    resp_rate:'частота дыхания (трекер)', temp:'ночная температура (трекер)' };
  const _skLabels = [...sk].map(k => _SKIP_LBL[k]).filter(Boolean);
  const skipNote = sk.size
    ? '⚠️ ВАЖНО: часть данных клиент НЕ вводил (помечены «не указано»): ' + (_skLabels.join(', ') || '—') + '. НЕ интерпретируй эти показатели, НЕ приписывай значения и НЕ строй на них выводы. Если часть блока клиент УЖЕ указал (например, часы сна и ночные пробуждения есть, а «ощущение сна» — нет) — НЕ говори, что данных о сне/энергии нет; в «Общей картине» мягко предложи уточнить ТОЛЬКО конкретные недостающие пункты из списка выше (один-два, без давления, без общих фраз вроде «внесите данные о сне»). Приборные показатели (кольцо/трекер) проси только если клиент упоминает устройство.\n\n'
    : '';

  // ── KB PATTERN SELECTION ──────────────────────────────────────
  const kbPatterns = selectKBPatterns(data);
  const kbBlock = kbPatterns.length
    ? '══ АКТИВНЫЕ КЛИНИЧЕСКИЕ ПАТТЕРНЫ ══\n'
      + 'Используй из базы знаний: ' + kbPatterns.join(', ') + '\n\n'
    : '';

  // ── ASSEMBLE USER MESSAGE ─────────────────────────────────────
  const patternBlock   = patterns.length  ? '══ БИОМЕТРИЧЕСКИЕ ПАТТЕРНЫ ══\n' + patterns.join('\n') + '\n\n' : '';
  const circadianBlock = circadian.length ? '══ ПАТТЕРНЫ СНА ══\n' + circadian.join('\n') + '\n\n' : '';
  const symptomBlock   = symRules.length  ? '══ СИМПТОМ → НУТРИТИВНАЯ ПОДДЕРЖКА ══\n' + symRules.join('\n') + '\n\n' : '';

  // ── ПОЛНЫЕ ДАННЫЕ АНКЕТЫ — чтобы НИ ОДНО введённое клиентом поле не потерялось в анализе ──
  const _J = a => (Array.isArray(a) && a.length) ? a.join(', ') : '—';
  // meds приходит массивом токенов-чекбоксов (VIO) — переводим в читаемые велнес-ярлыки,
  // иначе к ИИ уходят сырые коды («energy_factor,cycle_factor»). App Store 1.4.1 — без мед-названий.
  const _MEDS_LBL = { energy_factor:'фактор энергии/обмена', emotion_factor:'фактор настроения', cycle_factor:'фактор цикла', other_factor:'другой фактор',
                      thyroid:'фактор энергии/обмена', contraceptive:'фактор цикла', antidepressant:'фактор настроения' };
  const _medsStr = Array.isArray(data.meds)
    ? (data.meds.filter(Boolean).map(m => _MEDS_LBL[m] || m).join(', ') || '—')
    : (data.meds ? (_MEDS_LBL[data.meds] || data.meds) : '—');
  const fullDataBlock =
      '\n══ ПОЛНЫЕ ДАННЫЕ АНКЕТЫ — это ввёл клиент; ОБЯЗАТЕЛЬНО учти КАЖДЫЙ пункт ниже в разборе и рекомендациях, ничего не игнорируй ══\n'
    + ((data.goal || (Array.isArray(data.priorities) && data.priorities.length)) ? '🎯 ЦЕЛЬ КЛИЕНТА: ' + (data.goal ? String(data.goal).trim().slice(0, 300) : '—') + ((Array.isArray(data.priorities) && data.priorities.length) ? ' | приоритеты/фокус: ' + data.priorities.join(', ') : '') + ' — ПОДСТРОЙ разбор, акценты и рекомендации под эту цель клиента.\n' : '')
    + 'Питание · ограничения/диета: ' + _J(data.diet_restrict) + ' | режим питания: ' + (data.eating_pattern || '—') + '\n'
    + ((data.protein_intake || data.appetite || data.cravings || data.allergy) ? 'Питание (доп.): ' + [(data.protein_intake ? 'потребление белка: ' + data.protein_intake : ''), (data.appetite ? 'аппетит: ' + data.appetite : ''), (data.cravings ? 'тяга к сладкому/еде: да' : ''), (data.allergy ? 'аллергии: ' + data.allergy : '')].filter(Boolean).join(' | ') + '\n' : '')
    + ((data.memory || data.fog) ? 'Ясность ума · память: ' + (data.memory || '—') + ' | туман в голове: ' + (data.fog || '—') + '\n' : '')
    + (data.new_symptoms ? 'Новые симптомы за неделю (со слов клиента, сигнал — обрати внимание на тренд): ' + data.new_symptoms + '\n' : '')
    + (data.lifestyle_notes ? 'События/контекст недели (со слов клиента — учитывай как бытовое объяснение сдвигов метрик, не как ухудшение): ' + data.lifestyle_notes + '\n' : '')
    + 'Физическая активность · виды: ' + _J(data.act_types) + ' | частота: ' + (data.act_freq || '—') + ' | восстановление после нагрузки: ' + (data.act_recovery || '—') + (data.move_today ? ' | движение за прошедшие сутки: ' + ({sedentary:'сидячий день',light:'немного двигался',walk:'много ходил',cardio:'кардио/бег',strength:'силовая тренировка',active:'активный день'}[data.move_today] || data.move_today) : '') + '\n'
    + 'Добавки (принимает): ' + _J(data.supplements) + '\n'
    + 'Лекарства: ' + _medsStr + (data.meds_other ? ' | другие: ' + data.meds_other : '') + '\n'
    + 'Хронический стресс: ' + (data.chronic_stress || '—') + ' | симптомы кортизола: ' + _J(data.cortisol_symp) + '\n'
    + 'Гормональные симптомы: ' + ((Array.isArray(data.horm_symptoms) && data.horm_symptoms.length) ? _J(data.horm_symptoms) : ((data.horm_female || data.horm_male) ? (Object.entries(Object.assign({}, data.horm_female || {}, data.horm_male || {})).map(function(e){ return e[0] + ' (' + e[1] + ')'; }).join(', ') || '—') : '—')) + (data.horm_intensity ? ' | интенсивность: ' + data.horm_intensity : '') + '\n'
    + (isFem
        ? 'Цикл · статус: ' + (data.cycle_status || '—') + (data.heavy_period ? ' | обильные менструации: ' + (data.heavy_period === 'yes' ? 'да' : 'нет') : '') + ' | давность последней менструации: ' + (data.last_period || '—') + (data.cycle_len ? ' | длина цикла: ' + data.cycle_len + ' дн' : '') + (data.cycle_day ? ' | день цикла: ' + data.cycle_day : '') + (data.cycle_phase ? ' | фаза цикла: ' + data.cycle_phase : '') + '\n'
          + 'ПМС · тяжесть: ' + (data.pms || '—') + ' | симптомы: ' + _J(data.pms_symptoms) + '\n'
        : 'Мужское здоровье · витальность: ' + (data.vitality || '—') + ' | настроение/мотивация: ' + (data.male_mood || '—') + '\n')
    + 'Риск по костям: ' + _J(data.bone_risk) + '\n'
    + (function(d){ if(!d) return '';
        var p=[
          (d.vo2!=null ? 'VO₂max (аэробная форма) ' + d.vo2 : ''),
          (d.spo2!=null ? 'SpO₂ ' + d.spo2 + '%' : ''),
          (d.readiness!=null ? 'готовность ' + d.readiness : ''),
          (d.sleepHours!=null ? 'сон ' + d.sleepHours + ' ч' : ''),
          (d.deepMin!=null ? 'глубокий сон ' + d.deepMin + ' мин' : ''),
          (d.tempDev!=null ? 'отклонение температуры ' + d.tempDev + '°C' : '')
        ].filter(Boolean);
        return p.length ? 'Приборные показатели с трекера: ' + p.join(', ') + '\n' : '';
      })(data.device)
    + 'ИНСТРУКЦИЯ: каждый ненулевой пункт выше должен быть отражён в анализе хотя бы одной конкретной нутритивной рекомендацией или комментарием; пункты «—» (не указано) не интерпретируй.\n'
    + 'ЗАМЕТНО ОТКЛОНЁННЫЕ ПОКАЗАТЕЛИ ТРЕКЕРА НЕ ЗАМАЛЧИВАЙ: если кислород в крови (SpO₂) ниже ~94%, HRV очень низкий, пульс покоя высокий или температура заметно отклонена — обязательно мягко назови это в паттерн-рамке (напр. «показатель кислорода в крови ниже обычного диапазона», «вариабельность пульса ниже обычного»), БЕЗ диагноза и БЕЗ названий болезней/состояний (НЕ «апноэ», НЕ «гипоксия»), и добавь «если так держится — это стоит спокойно обсудить со специалистом». Такие показатели НЕЛЬЗЯ просто проигнорировать в тексте.\n';

  // Пункт A: ЛИЧНАЯ норма клиента (медиана прошлых дней из vial_daily) — чтобы ИИ сравнивал
  // сегодня с индивидуальным baseline, а не только с общими референсами.
  const baselineBlock = (function(b){
    if(!b || !b.metrics) return '';
    const lbl = { sleep_qual:'Качество сна', energy:'Энергия', rhr:'Пульс покоя', sleep_hours:'Часы сна', weight:'Вес (кг)', waist:'Талия (см)' };
    const unit = { weight:' кг', waist:' см' };
    const neutral = { weight:1, waist:1 };   // вес/талия: рост/снижение не «хорошо/плохо» — нейтрально
    const today = { sleep_qual:sleepQual, energy:energyVal, rhr:rhrVal, sleep_hours:(parseFloat(data.sleep_hours)||null), weight:(parseFloat(data.weight)||null), waist:(parseFloat(data.waist)||null) };
    const rows = Object.keys(b.metrics).map(function(k){
      const m=b.metrics[k]; if(!m||m.usual==null) return '';
      const t=today[k]; let cmp='';
      if(t!=null){
        const d=t-m.usual, thr=neutral[k]?(k==='weight'?1.5:2):Math.max(Math.abs(m.usual)*0.1,0.5);
        if(Math.abs(d)<thr) cmp=' → как обычно';
        else if(neutral[k]) cmp=(d>0?' → выше обычного':' → ниже обычного');
        else { const better=(k==='rhr')?d<0:d>0; cmp=(better?' → лучше личной нормы':' → хуже личной нормы'); }
      }
      const u=unit[k]||'';
      return '• '+(lbl[k]||k)+': обычно ~'+m.usual+u+(t!=null?(', сегодня '+t+u):'')+cmp+'\n';
    }).filter(Boolean).join('');
    if(!rows) return '';
    return '══ ЛИЧНАЯ НОРМА КЛИЕНТА (по '+(b.days||0)+' предыдущим дням) ══\n'
      + rows
      + 'ВАЖНО: сравнивай сегодняшние значения с ЛИЧНОЙ нормой клиента выше, а не только с общими референсами. '
      + 'Если сегодня хуже личной нормы — мягко отметь это и дай велнес-акцент; если лучше или как обычно — поддержи.\n\n';
  })(data.baseline);

  const _feed = skipNote
    + '══ РЕФЕРЕНСНЫЕ НОРМЫ ══\n'
    + 'HRV (' + age + ' лет): норма ' + hrvNormLow + '–' + hrvNormHigh + ' мс | клиент: ' + SK('hrv', data.hrv + ' мс → ' + hrvStatus) + '\n'
    + 'ЧСС покоя: норма ' + (isFem ? '60–75' : '55–70') + ' уд/мин | клиент: ' + SK('rhr', rhrVal + ' уд/мин → ' + rhrStatus) + '\n'
    + 'Глубокий сон: норма 90–110 мин | клиент: ' + SK('deep', deepContext) + '\n'
    + 'Частота дыхания: норма покоя 12–20 вд/мин | клиент: ' + SK('resp_rate', respRate + ' вд/мин' + (respRate > 20 ? ' [выше нормы]' : '')) + '\n'
    + 'Качество сна: ' + SK('sleep_qual', sleepQual + '/10 → ' + sleepStatus) + '\n\n'

    + baselineBlock
    + patternBlock
    + circadianBlock
    + symptomBlock
    + kbBlock

    + '══ ' + phaseName.toUpperCase() + ' ══\n'
    + phaseProtocol + '\n\n'

    + '══ ДАННЫЕ КЛИЕНТА ══\n'
    + (data.name ? 'Имя: ' + String(data.name).trim().slice(0, 40) + '\n' : '')
    + 'Пол: ' + (isFem ? 'Женщина' : 'Мужчина') + ' | Фаза: ' + phaseName
    // Велнес: фаза — контекст, а не диагноз. Голый ярлык провоцировал «вы в андропаузе» как факт + вынос
    // в заголовки 8 раз (живой VIO 14.07). Держим pattern-рамку прямо у ярлыка, где модель его читает.
    + (isWell ? ' (это ВОЗРАСТНОЙ КОНТЕКСТ для подбора акцентов, НЕ утверждение про клиента: НЕ пиши «вы в '
        + phaseName.toLowerCase() + '», НЕ выноси «' + phaseName.toLowerCase() + '» в заголовки тем и НЕ повторяй '
        + 'это слово в каждой теме. Упомяни фазу МЯГКО и не более одного раза — как паттерн: «в этом периоде тело чаще…». '
        + 'Заголовки тем — про рычаг (сон, питание, движение), а не про фазу.)' : '')
    + (data.age    ? ' | Возраст: ' + data.age + ' лет' : '')
    + (data.weight ? ' | Вес: ' + data.weight + ' кг'   : '')
    + (data.height ? ' | Рост: ' + data.height + ' см'  : '')
    + (bmiCalc     ? ' | ИМТ: ' + bmiCalc.toFixed(1) + ' кг/м² (' + bmiCat + ')' : '')
    + (waistCm     ? ' | Талия: ' + waistCm + ' см'     : '')
    + (whtrCalc    ? ' | WHtR: ' + whtrCalc.toFixed(2) + ' (' + whtrCat + ')' : '') + '\n'
    // Велнес НЕ назначает диету: цифру дефицита («−15–20% / −300–400 ккал») в VIO/PRO не шлём — это назначение
    // (живой PRO 14.07 выдал «дефицит 300–400 ккал в день»). Оставляем нейтральный ориентир поддержания + приоритет белку.
    + (bmrCalc ? (isWell
        ? 'Энергобаланс (расчёт, не биоимпеданс): ориентир поддержания веса ~' + maintLow + '–' + maintHigh + ' ккал/день. Акцент — качественный белок и цельная еда, а не подсчёт калорий.\n'
        : 'Энергобаланс (расчёт, не биоимпеданс): BMR ~' + bmrCalc + ' ккал/день (Mifflin-St Jeor); ориентир поддержания веса ~' + maintLow + '–' + maintHigh + ' ккал/день (малоподвижный→лёгкая активность). Для снижения веса — дефицит ~15–20% от поддержания, не ниже BMR; приоритет белку ' + (isFem ? '1.6–2.2' : '1.6–2.0') + ' г/кг.\n') : '')
    + 'HRV: ' + SK('hrv', data.hrv + ' мс (' + hrvStatus + ')') + ' | Тренд: ' + SK('hrv_trend', (data.hrv_trend === 'below' ? 'падает' : data.hrv_trend === 'above' ? 'растёт' : 'стабилен')) + '\n'
    + 'Сон: ' + SK('sleep_qual', sleepQual + '/10') + (data.sleep_hours ? ' | Часов сна: ' + data.sleep_hours + ' ч' : '') + ' | Глубокий: ' + SK('deep', deepContext) + ' | Пробуждения: ' + SK('wake', wakeVal) + '\n'
    + (sk.has('hf_count') ? 'Приливы: не указано (клиент не вводил)' : hfContext) + '\n'
    + 'Дыхание: ' + SK('resp_rate', respRate + ' вд/мин') + ' | Пульс покоя: ' + SK('rhr', rhrVal + ' уд/мин') + '\n'
    + 'Энергия: ' + SK('energy', energyVal + '/10') + ' | Тревога: ' + SK('anxiety', anxietyVal + '/10') + ' | Настроение: ' + SK('mood', data.mood) + ' | Раздражительность: ' + SK('irritability', data.irritability) + '\n'
    + 'Температура ночью: ' + SK('temp', data.temp) + ' | Стресс: ' + SK('stress', data.stress) + ' | Алкоголь вчера: ' + data.alc + '\n'
    + 'Симптомы: ' + (symptoms.length ? symptoms.join(', ') : 'не указаны') + '\n'
    + complaintsContext
    + bioContext + '\n'
    + (data.training && data.training.count ? 'Тренировки (с кольца, 7 дн): ' + data.training.count + ' сессий' + (data.training.intensity ? ', последняя интенсивность ' + data.training.intensity : '') + (data.training.activity ? ' (' + data.training.activity + ')' : '') + '. Применяй HRV-направленную нагрузку: тяжёлые/интенсивные сессии — только в дни восстановленного ночного HRV; падающий HRV неделю → снизить объём, добавить сон/восстановление.\n' : '')
    + labsContext
    + fullDataBlock;

  // VIO/PRO (App Store) — прогнать «корм» через велнес-фильтр; EXPERT/ELITE (клиника) — как есть.
  return ['vio', 'pro'].includes(String(tier || '').toLowerCase()) ? deMedicalizeFeed(_feed) : _feed;
}

